16	
17	package org.springframework.samples.petclinic.util;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	
21	import java.time.LocalDate;
22	
23	/**
24	 * Computes an owner's membership standing from its stored fields. An owner earns
25	 * {@link #membershipPoints(Owner) membership points} — starting at 0 and gaining
26	 * {@link #EMAIL_POINTS} for a present email, {@link #SOLE_NAMESAKE_POINTS} for having no
27	 * namesakes (a {@code namesakeCount} of 0), {@link #LARGE_HOUSEHOLD_POINTS} for a household of
28	 * {@link #LARGE_HOUSEHOLD_SIZE} or more, and {@link #TENURE_POINTS} once tenure exceeds
29	 * {@link #TENURE_THRESHOLD_FISCAL_YEARS} fiscal years. Those points map to a numeric
30	 * {@link #membershipLevel(Owner) membership level} from {@link #MIN_LEVEL} to {@link #MAX_LEVEL}.
31	 */
32	public abstract class MembershipLevelCalculator {
33	
34	    /** Points awarded when the owner has an email address. */
35	    public static final int EMAIL_POINTS = 2;
36	
37	    /** Points awarded when the owner has no namesakes (a {@code namesakeCount} of 0). */
38	    public static final int SOLE_NAMESAKE_POINTS = 1;
39	
40	    /** Household size, in members, at or above which the large-household points are awarded. */
41	    public static final int LARGE_HOUSEHOLD_SIZE = 3;
42	
43	    /** Points awarded when the owner belongs to a household of {@link #LARGE_HOUSEHOLD_SIZE} or more. */
44	    public static final int LARGE_HOUSEHOLD_POINTS = 2;
45	
46	    /** Elapsed fiscal years an owner's tenure must exceed to earn the tenure points. */
47	    public static final long TENURE_THRESHOLD_FISCAL_YEARS = 1;
48	
49	    /** Points awarded when the owner's tenure exceeds {@link #TENURE_THRESHOLD_FISCAL_YEARS} fiscal years. */
50	    public static final int TENURE_POINTS = 3;
51	
52	    /** Lowest level this calculator awards, given to owners scoring 0-1 points. */
53	    public static final int MIN_LEVEL = 1;
54	
55	    /** Highest level this calculator awards, reached once an owner scores 6 or more points. */
56	    public static final int MAX_LEVEL = 4;
57	
58	    /**
59	     * Return the membership points for the given owner: 0 plus {@link #EMAIL_POINTS} when an
60	     * email is present, {@link #SOLE_NAMESAKE_POINTS} when {@code namesakeCount} is 0,
61	     * {@link #LARGE_HOUSEHOLD_POINTS} for a household of {@link #LARGE_HOUSEHOLD_SIZE} or more,
62	     * and {@link #TENURE_POINTS} when tenure exceeds {@link #TENURE_THRESHOLD_FISCAL_YEARS} fiscal years.
63	     */
64	    public static int membershipPoints(Owner owner) {
65	        int points = 0;
66	        if (owner.hasEmail()) {
67	            points += EMAIL_POINTS;
68	        }
69	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
70	            points += SOLE_NAMESAKE_POINTS;
71	        }
72	        if (hasLargeHousehold(owner)) {
73	            points += LARGE_HOUSEHOLD_POINTS;
74	        }
75	        if (hasQualifyingTenure(owner)) {
76	            points += TENURE_POINTS;
77	        }
78	        return points;
79	    }
80	
81	    /**
82	     * Return the membership level for the given owner, mapped from its
83	     * {@link #membershipPoints(Owner) membership points}: level 1 for 0-1 points, 2 for 2-3,
84	     * 3 for 4-5, and {@link #MAX_LEVEL} for 6 or more.
85	     */
86	    public static int membershipLevel(Owner owner) {
87	        int points = membershipPoints(owner);
88	        return Math.min(MAX_LEVEL, MIN_LEVEL + points / 2);
89	    }
90	
91	    /**
92	     * Whether the owner belongs to a household of {@link #LARGE_HOUSEHOLD_SIZE} or more members.
93	     * An owner with no recorded household size is treated as not qualifying.
94	     */
95	    private static boolean hasLargeHousehold(Owner owner) {
96	        Integer householdSize = owner.getHouseholdSize();
97	        return householdSize != null && householdSize >= LARGE_HOUSEHOLD_SIZE;
98	    }
99	
100	    /**
101	     * Whether the owner's tenure, measured as the fiscal years elapsed from its registration
102	     * date to today, exceeds {@link #TENURE_THRESHOLD_FISCAL_YEARS}. An owner with no
103	     * registration date has no tenure.
104	     */
105	    private static boolean hasQualifyingTenure(Owner owner) {
106	        LocalDate registrationDate = owner.getRegistrationDate();
107	        if (registrationDate == null) {
108	            return false;
109	        }
110	        return FiscalYearResolver.elapsedYears(registrationDate, LocalDate.now())
111	            > TENURE_THRESHOLD_FISCAL_YEARS;
112	    }
113	
114	}
